const body = $json.body || $json;
const message = String(body.message || '').trim();
if (!message) throw new Error('Пустое сообщение');

const context = body.clientContext && typeof body.clientContext === 'object' ? body.clientContext : {};
const history = Array.isArray(body.chatHistory) ? body.chatHistory.slice(-16) : [];

const instructions = `Ты — AI-ассистент специалиста по психологическому консультированию. Ты помогаешь специалисту анализировать материалы только выбранного клиента и готовиться к дальнейшей работе.

Правила:
- используй только данные, которые переданы в контексте выбранного клиента;
- никогда не придумывай события, травмы, диагнозы, убеждения или факты, которых нет в данных;
- если делаешь вывод, предположение или рабочую гипотезу, прямо называй это гипотезой;
- не выдавай медицинский или психиатрический диагноз как факт;
- различай слова клиента, записи специалиста и свою интерпретацию;
- если данных недостаточно, прямо скажи, чего не хватает и что можно уточнить;
- отвечай практично: что видно по данным, на что обратить внимание, какие вопросы можно задать, что можно проверить на следующей сессии;
- не упоминай других клиентов и не предполагай, что у тебя есть доступ к ним;
- платежные данные не используются для психологического анализа.

Отвечай по-русски, если специалист явно не попросил другой язык.`;

const historyText = history.map(x => `${x.role === 'assistant' ? 'AI' : 'Специалист'}: ${String(x.text || '').trim()}`).filter(Boolean).join('\n');
const prompt = `ВЫБРАННЫЙ КЛИЕНТ: ${String(body.clientName || '').trim() || 'Без имени'}

КОНТЕКСТ КЛИЕНТА (JSON):
${JSON.stringify(context)}

ПОСЛЕДНИЕ СООБЩЕНИЯ ЧАТА:
${historyText || 'Истории пока нет.'}

НОВЫЙ ВОПРОС СПЕЦИАЛИСТА:
${message}

Ответь специалисту по существу. Если ссылаешься на факт, укажи источник внутри контекста: анкета, запрос, диагностика, сессия или заметка. Гипотезы отделяй от фактов.`;

return [{json:{accessKey:String(body.accessKey || ''),clientId:String(body.clientId || ''),clientName:String(body.clientName || ''),instructions,prompt}}];

const r=$json||{};
let text=String(r.output_text||'').trim();
if(!text&&Array.isArray(r.output)){for(const item of r.output){for(const part of item?.content||[]){if(part?.type==='output_text'&&part?.text)text+=String(part.text);}}}
text=text.trim();
if(!text)throw new Error('OpenAI не вернул текст');
return [{json:{reply:text}}];
